PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE asset (
	id INTEGER NOT NULL, 
	name VARCHAR(100) NOT NULL, 
	code VARCHAR(50) NOT NULL, 
	status VARCHAR(20), 
	criticality VARCHAR(20), 
	site_id INTEGER NOT NULL, 
	category_id INTEGER NOT NULL, location_id INTEGER REFERENCES location(id), subcategory_id INTEGER REFERENCES sub_category(id), project_code VARCHAR(50), start_date DATETIME, end_date DATETIME, estimated_hours FLOAT, description TEXT, storage_aisle VARCHAR(50), storage_row VARCHAR(50), storage_bin VARCHAR(50), notes TEXT, make VARCHAR(100), model VARCHAR(100), serial_number VARCHAR(100), barcode VARCHAR(100), replacement_value FLOAT DEFAULT 0.0, is_chiller BOOLEAN DEFAULT 0, api_chiller_id VARCHAR(50), 
	PRIMARY KEY (id), 
	UNIQUE (code), 
	FOREIGN KEY(site_id) REFERENCES site (id), 
	FOREIGN KEY(category_id) REFERENCES category (id)
);
CREATE TABLE asset_business (
	id INTEGER NOT NULL, 
	asset_id INTEGER NOT NULL, 
	vendor_id INTEGER NOT NULL, 
	supplier_part_number VARCHAR(100), 
	catalog VARCHAR(100), 
	price FLOAT, 
	is_preferred BOOLEAN, 
	PRIMARY KEY (id), 
	FOREIGN KEY(asset_id) REFERENCES asset (id), 
	FOREIGN KEY(vendor_id) REFERENCES vendor (id)
);
CREATE TABLE asset_custom_field (
	id INTEGER NOT NULL, 
	asset_id INTEGER NOT NULL, 
	field_name VARCHAR(100) NOT NULL, 
	field_value TEXT, expiry_date DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(asset_id) REFERENCES asset (id)
);
CREATE TABLE asset_file (
	id INTEGER NOT NULL, 
	asset_id INTEGER NOT NULL, 
	file_name VARCHAR(255) NOT NULL, 
	file_path VARCHAR(500) NOT NULL, 
	is_url BOOLEAN, 
	notes VARCHAR(255), 
	upload_date DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(asset_id) REFERENCES asset (id)
);
CREATE TABLE asset_meter (
	id INTEGER NOT NULL, 
	asset_id INTEGER NOT NULL, 
	name VARCHAR(100) NOT NULL, 
	unit VARCHAR(50), mqtt_broker VARCHAR(255), mqtt_port INTEGER DEFAULT 1883, mqtt_topic VARCHAR(255), mqtt_payload_key VARCHAR(100), 
	PRIMARY KEY (id), 
	FOREIGN KEY(asset_id) REFERENCES asset (id)
);
CREATE TABLE asset_meter_reading (
	id INTEGER NOT NULL, 
	meter_id INTEGER NOT NULL, 
	reading_value FLOAT NOT NULL, 
	reading_date DATETIME, 
	user_id INTEGER, 
	PRIMARY KEY (id), 
	FOREIGN KEY(meter_id) REFERENCES asset_meter (id), 
	FOREIGN KEY(user_id) REFERENCES user (id)
);
CREATE TABLE asset_part_bom (
	id INTEGER NOT NULL, 
	asset_id INTEGER NOT NULL, 
	part_id INTEGER NOT NULL, 
	quantity FLOAT, 
	note VARCHAR(255), 
	PRIMARY KEY (id), 
	FOREIGN KEY(asset_id) REFERENCES asset (id), 
	FOREIGN KEY(part_id) REFERENCES part (id)
);
CREATE TABLE asset_personnel (
	id INTEGER NOT NULL, 
	asset_id INTEGER NOT NULL, 
	user_id INTEGER NOT NULL, 
	notify_on_status_change BOOLEAN, 
	notify_on_wo BOOLEAN, 
	PRIMARY KEY (id), 
	FOREIGN KEY(asset_id) REFERENCES asset (id), 
	FOREIGN KEY(user_id) REFERENCES user (id)
);
CREATE TABLE asset_warranty (
	id INTEGER NOT NULL, 
	asset_id INTEGER NOT NULL, 
	type VARCHAR(50), 
	provider VARCHAR(100), 
	lifespan VARCHAR(100), 
	expiry_date DATETIME, 
	cert_number VARCHAR(100), 
	description TEXT, 
	PRIMARY KEY (id), 
	FOREIGN KEY(asset_id) REFERENCES asset (id)
);
CREATE TABLE category (
	id INTEGER NOT NULL, 
	name VARCHAR(100) NOT NULL, 
	type VARCHAR(20), 
	PRIMARY KEY (id)
);
CREATE TABLE checklist (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                name VARCHAR(100) NOT NULL UNIQUE,
                created_at DATETIME
            , project_code VARCHAR(20));
CREATE TABLE checklist_parameter_template (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                checklist_id INTEGER NOT NULL,
                parameter VARCHAR(100) NOT NULL,
                standard VARCHAR(100) NOT NULL, position INTEGER DEFAULT 0,
                FOREIGN KEY(checklist_id) REFERENCES checklist(id)
            );
CREATE TABLE chiller_fault_code (
	id INTEGER NOT NULL, 
	chiller_type VARCHAR(100) NOT NULL, 
	category VARCHAR(50) NOT NULL, 
	fault_code VARCHAR(50) NOT NULL, 
	description VARCHAR(255) NOT NULL, 
	PRIMARY KEY (id)
);
CREATE TABLE custom_dashboard (
	id INTEGER NOT NULL, 
	user_id INTEGER NOT NULL, 
	name VARCHAR(100) NOT NULL, 
	icon VARCHAR(50), 
	position INTEGER, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES user (id)
);
CREATE TABLE custom_dashboard_widget (
	id INTEGER NOT NULL, 
	dashboard_id INTEGER NOT NULL, 
	title VARCHAR(100) NOT NULL, 
	widget_type VARCHAR(50), 
	data_source VARCHAR(50) NOT NULL, 
	data_config TEXT, 
	position INTEGER, 
	col_span INTEGER, 
	color VARCHAR(20), 
	PRIMARY KEY (id), 
	FOREIGN KEY(dashboard_id) REFERENCES custom_dashboard (id)
);
CREATE TABLE custom_sidebar_link (
	id INTEGER NOT NULL, 
	user_id INTEGER NOT NULL, 
	label VARCHAR(100) NOT NULL, 
	url VARCHAR(500) NOT NULL, 
	icon VARCHAR(50), 
	position INTEGER, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES user (id)
);
CREATE TABLE helpdesk_location (
	id INTEGER NOT NULL, 
	name VARCHAR(255) NOT NULL, site_id INTEGER REFERENCES site(id), 
	PRIMARY KEY (id), 
	UNIQUE (name)
);
CREATE TABLE helpdesk_module (
	id INTEGER NOT NULL, 
	name VARCHAR(100) NOT NULL, site_id INTEGER REFERENCES site(id), 
	PRIMARY KEY (id), 
	UNIQUE (name)
);
CREATE TABLE helpdesk_progress (
	id INTEGER NOT NULL, 
	ticket_id INTEGER NOT NULL, 
	user_id INTEGER NOT NULL, 
	description TEXT NOT NULL, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(ticket_id) REFERENCES helpdesk_ticket (id), 
	FOREIGN KEY(user_id) REFERENCES user (id)
);

','2026-04-22 06:40:47.897128');
CREATE TABLE helpdesk_progress_file (
	id INTEGER NOT NULL, 
	progress_id INTEGER NOT NULL, 
	file_path VARCHAR(500) NOT NULL, 
	upload_date DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(progress_id) REFERENCES helpdesk_progress (id)
);
CREATE TABLE helpdesk_ticket (
	id INTEGER NOT NULL, 
	ticket_code VARCHAR(50) NOT NULL, 
	subject VARCHAR(255) NOT NULL, 
	description TEXT NOT NULL, 
	company VARCHAR(100), 
	is_internal BOOLEAN, 
	divisi_tujuan VARCHAR(100), 
	modul VARCHAR(100), 
	location_subject VARCHAR(255), 
	ticket_type VARCHAR(100), 
	partner VARCHAR(100), 
	person_name VARCHAR(100), 
	email VARCHAR(100), 
	mobile VARCHAR(50), 
	team VARCHAR(100), 
	team_head VARCHAR(100), 
	assigned_user_id INTEGER, 
	priority VARCHAR(50), 
	tags VARCHAR(255), 
	scheduled_start_date DATETIME, 
	scheduled_end_date DATETIME, 
	actual_end_date DATETIME, 
	status VARCHAR(50), 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	UNIQUE (ticket_code), 
	FOREIGN KEY(assigned_user_id) REFERENCES user (id)
);
CREATE TABLE helpdesk_ticket_log (
	id INTEGER NOT NULL, 
	ticket_id INTEGER NOT NULL, 
	user_id INTEGER NOT NULL, 
	log_text TEXT NOT NULL, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(ticket_id) REFERENCES helpdesk_ticket (id), 
	FOREIGN KEY(user_id) REFERENCES user (id)
);
CREATE TABLE helpdesk_ticket_technician (
	ticket_id INTEGER NOT NULL, 
	user_id INTEGER NOT NULL, 
	PRIMARY KEY (ticket_id, user_id), 
	FOREIGN KEY(ticket_id) REFERENCES helpdesk_ticket (id), 
	FOREIGN KEY(user_id) REFERENCES user (id)
);
CREATE TABLE location (
	id INTEGER NOT NULL, 
	name VARCHAR(100) NOT NULL, 
	description VARCHAR(255), 
	site_id INTEGER NOT NULL, category_id INTEGER REFERENCES category(id), 
	PRIMARY KEY (id), 
	FOREIGN KEY(site_id) REFERENCES site (id)
);
CREATE TABLE part (
	id INTEGER NOT NULL, 
	name VARCHAR(100) NOT NULL, 
	code VARCHAR(50) NOT NULL, 
	make VARCHAR(50), 
	model_num VARCHAR(50), 
	unit_cost FLOAT, 
	site_id INTEGER, 
	PRIMARY KEY (id), 
	UNIQUE (code), 
	FOREIGN KEY(site_id) REFERENCES category (id)
);
CREATE TABLE po_item (
	id INTEGER NOT NULL, 
	po_id INTEGER NOT NULL, 
	part_id INTEGER NOT NULL, 
	quantity FLOAT, 
	unit_cost FLOAT, 
	line_total FLOAT, 
	PRIMARY KEY (id), 
	FOREIGN KEY(po_id) REFERENCES purchase_order (id), 
	FOREIGN KEY(part_id) REFERENCES part (id)
);
CREATE TABLE project_code (
	id INTEGER NOT NULL, 
	code VARCHAR(50) NOT NULL, 
	description VARCHAR(255), 
	PRIMARY KEY (id), 
	UNIQUE (code)
);
CREATE TABLE purchase_order (
	id INTEGER NOT NULL, 
	po_number VARCHAR(50) NOT NULL, 
	status VARCHAR(20), 
	vendor_id INTEGER NOT NULL, 
	site_id INTEGER NOT NULL, 
	requested_by INTEGER, 
	total_cost FLOAT, 
	date_created DATETIME, 
	PRIMARY KEY (id), 
	UNIQUE (po_number), 
	FOREIGN KEY(vendor_id) REFERENCES vendor (id), 
	FOREIGN KEY(site_id) REFERENCES site (id), 
	FOREIGN KEY(requested_by) REFERENCES user (id)
);
CREATE TABLE site (
	id INTEGER NOT NULL, 
	name VARCHAR(100) NOT NULL, 
	address VARCHAR(255), 
	timezone VARCHAR(50), api_site_id VARCHAR(50), project_code VARCHAR(50), 
	PRIMARY KEY (id)
);
CREATE TABLE site_safe_range (
	id INTEGER NOT NULL, 
	site_id INTEGER NOT NULL, 
	parameter_key VARCHAR(100) NOT NULL, 
	min_value FLOAT, 
	max_value FLOAT, 
	PRIMARY KEY (id), 
	FOREIGN KEY(site_id) REFERENCES site (id)
);
CREATE TABLE stock_level (
	id INTEGER NOT NULL, 
	part_id INTEGER NOT NULL, 
	site_id INTEGER NOT NULL, 
	qty_on_hand INTEGER, 
	min_qty INTEGER, 
	aisle VARCHAR(20), 
	bin_number VARCHAR(20), 
	"row" VARCHAR(20), 
	PRIMARY KEY (id), 
	FOREIGN KEY(part_id) REFERENCES part (id), 
	FOREIGN KEY(site_id) REFERENCES site (id)
);
CREATE TABLE sub_category (
	id INTEGER NOT NULL, 
	name VARCHAR(100) NOT NULL, 
	category_id INTEGER NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(category_id) REFERENCES category (id)
);
CREATE TABLE tasklist (
	id INTEGER NOT NULL, 
	name VARCHAR(100) NOT NULL, 
	description TEXT, project_code VARCHAR(20), 
	PRIMARY KEY (id)
);
CREATE TABLE tasklist_procedure (
	id INTEGER NOT NULL, 
	tasklist_id INTEGER NOT NULL, 
	name VARCHAR(255) NOT NULL, 
	requires_attachment BOOLEAN, estimated_minutes INTEGER DEFAULT 0, position INTEGER DEFAULT 0, min_photos INTEGER DEFAULT 0, 
	PRIMARY KEY (id), 
	FOREIGN KEY(tasklist_id) REFERENCES tasklist (id)
);
CREATE TABLE team (
	id INTEGER NOT NULL, 
	name VARCHAR(100) NOT NULL, 
	description TEXT, 
	site_id INTEGER NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(site_id) REFERENCES site (id)
);
CREATE TABLE user (
	id INTEGER NOT NULL, 
	nrp VARCHAR(64) NOT NULL, 
	name VARCHAR(120) NOT NULL, 
	password_hash VARCHAR(256), 
	role VARCHAR(20), site_id INTEGER REFERENCES site(id), team_id INTEGER REFERENCES team(id), phone_number VARCHAR(20), last_login DATETIME, login_count INTEGER DEFAULT 0, 
	PRIMARY KEY (id)
);
CREATE TABLE user_dashboard_widget (
	id INTEGER NOT NULL, 
	user_id INTEGER NOT NULL, 
	widget_key VARCHAR(50) NOT NULL, 
	position INTEGER, 
	col_span INTEGER, 
	is_visible BOOLEAN, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES user (id)
);
CREATE TABLE vendor (
	id INTEGER NOT NULL, 
	name VARCHAR(100) NOT NULL, 
	trade VARCHAR(100), 
	contact_info TEXT, 
	PRIMARY KEY (id)
);
CREATE TABLE wo_assignees (
	work_order_id INTEGER NOT NULL, 
	user_id INTEGER NOT NULL, 
	PRIMARY KEY (work_order_id, user_id), 
	FOREIGN KEY(work_order_id) REFERENCES work_order (id), 
	FOREIGN KEY(user_id) REFERENCES user (id)
);
CREATE TABLE work_instruction_checklist (
	id INTEGER NOT NULL, 
	work_instruction_id INTEGER NOT NULL, 
	task VARCHAR(255) NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(work_instruction_id) REFERENCES work_instruction (id)
);
CREATE TABLE work_order (
	id INTEGER NOT NULL, 
	code VARCHAR(50) NOT NULL, 
	description TEXT NOT NULL, 
	status VARCHAR(20), 
	priority VARCHAR(20), 
	maintenance_type VARCHAR(50), 
	date_created DATETIME, 
	asset_id INTEGER NOT NULL, 
	assigned_to INTEGER, project_code VARCHAR(50), start_date DATETIME, end_date DATETIME, estimated_hours FLOAT, suggested_completion_date DATETIME, work_instructions TEXT, status_id INTEGER REFERENCES work_order_status(id), tasklist_id INTEGER REFERENCES tasklist(id), checklist_id INTEGER REFERENCES checklist(id), suggested_start_date DATETIME, team_id INTEGER REFERENCES team(id), helpdesk_ticket_id INTEGER REFERENCES helpdesk_ticket(id), customer_name VARCHAR(100), customer_title VARCHAR(100), customer_signature TEXT, technician_signature TEXT, 
	PRIMARY KEY (id), 
	UNIQUE (code), 
	FOREIGN KEY(asset_id) REFERENCES asset (id), 
	FOREIGN KEY(assigned_to) REFERENCES user (id)
);

