CREATE TABLE work_order_part (
	id INTEGER NOT NULL, 
	work_order_id INTEGER NOT NULL, 
	part_id INTEGER NOT NULL, 
	quantity_used FLOAT, 
	date_added DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(work_order_id) REFERENCES work_order (id), 
	FOREIGN KEY(part_id) REFERENCES part (id)
);
CREATE TABLE work_order_procedure (
	id INTEGER NOT NULL, 
	work_order_id INTEGER NOT NULL, 
	tasklist_name VARCHAR(100) NOT NULL, 
	name VARCHAR(255) NOT NULL, 
	requires_attachment BOOLEAN, 
	is_completed BOOLEAN, 
	attachment_path VARCHAR(500), 
	completed_at DATETIME, 
	completed_by_id INTEGER, estimated_minutes INTEGER DEFAULT 0, status VARCHAR(50) DEFAULT 'Pending', notes TEXT, min_photos INTEGER DEFAULT 0, 
	PRIMARY KEY (id), 
	FOREIGN KEY(work_order_id) REFERENCES work_order (id), 
	FOREIGN KEY(completed_by_id) REFERENCES user (id)
);
CREATE TABLE work_order_status (
	id INTEGER NOT NULL, 
	name VARCHAR(50) NOT NULL, 
	description VARCHAR(255), 
	control_type VARCHAR(20), 
	PRIMARY KEY (id), 
	UNIQUE (name)
);
